        if color not in colors:
            colors[color] = []
        colors[color].append((r, c))

    output_grid = [row[:] for row in input_grid]

    # Find all diagonal pairs and sort them by start position
    diagonal_segments = []
    for color in sorted(colors.keys()):
        positions = colors[color]
        for i in range(len(positions)):
            for j in range(i + 1, len(positions)):
                (r1, c1) = positions[i]
                (r2, c2) = positions[j]

                if r2 > r1 and c2 > c1 and abs(r2 - r1) == abs(c2 - c1):
                    dr, dc = r2 - r1, c2 - c1
                    diagonal_segments.append({
                        'color': color,
                        'start': (r1, c1),
                        'end': (r2, c2),
                        'positions': positions[i+j:][:]  # from i to j
                    })

    # Sort by start position (row-major order)
    diagonal_segments.sort(key=lambda x: x['start'])

    # Process in order
    for seg in diagonal_segments:
        for k, (nr, nc) in enumerate(seg['positions']):
            # Fill cells between endpoints (not including endpoints)
            if k < len(seg['positions']) - 1 and 0 <= nr < rows and 0 <= nc < cols:
                if output_grid[nr][nc] == 4:
                    output_grid[nr][nc] = seg['color']

    return output_grid

