    for (r, c), color in non_bg_colors.items():
        if color not in colors:
            colors[color] = []
        colors[color].append((r, c))

    # Find all diagonal segments and which cells they cover
    all_cells = {}  # cell -> color
    for color in sorted(colors.keys()):
        positions = colors[color]
        for i in range(len(positions)):
            for j in range(i + 1, len(positions)):
                (r1, c1) = positions[i]
                (r2, c2) = positions[j]

                if r2 > r1 and c2 > c1 and abs(r2 - r1) == abs(c2 - c1):
                    dr, dc = r2 - r1, c2 - c1
                    steps = abs(dr)

                    middle_positions = []
                    for k in range(1, steps):
                        nr, nc = r1 + k * (dr // steps), c1 + k * (dc // steps)
                        middle_positions.append((nr, nc))

                    middle_positions_set = set(middle_positions)
                    # Count how many diagonals cover each cell
                    for (nr, nc) in middle_positions_set:
                        if all_cells.get((nr, nc), 0) == 0:
                            all_cells[(nr, nc)] = color
                        elif all_cells.get((nr, nc), 0) != color:
